using Servicio.RetazoMarket.Business.DTOs.MovimientoMaterial;
namespace Servicio.RetazoMarket.Business.Validators;
public static class MovimientoMaterialValidator { private static readonly HashSet<string> Tipos=["ING","EGR","AJP","AJN"];public static IReadOnlyCollection<string> ValidarCreacion(CrearMovimientoMaterialRequest r){var e=new List<string>();if(r is null)return ["La solicitud no puede ser nula."];if(r.id_material<=0)e.Add("El material es obligatorio.");var t=r.tipo_movimiento?.Trim().ToUpperInvariant();if(t is null||!Tipos.Contains(t))e.Add("El tipo debe ser ING, EGR, AJP o AJN.");if(r.cantidad<=0)e.Add("La cantidad debe ser mayor que cero.");if(decimal.Round(r.cantidad,3)!=r.cantidad)e.Add("La cantidad admite máximo tres decimales.");if(string.IsNullOrWhiteSpace(r.motivo_mov))e.Add("El motivo es obligatorio.");else if(r.motivo_mov.Trim().Length>100)e.Add("El motivo no puede exceder 100 caracteres.");if(r.metodo_pago?.Trim().Length>50)e.Add("El método de pago no puede exceder 50 caracteres.");return e;}public static IReadOnlyCollection<string> ValidarFiltro(MovimientoMaterialFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(!string.IsNullOrWhiteSpace(r.tipo_movimiento)&&!Tipos.Contains(r.tipo_movimiento.Trim().ToUpperInvariant()))e.Add("El tipo debe ser ING, EGR, AJP o AJN.");if(r.fecha_desde_utc>r.fecha_hasta_utc)e.Add("La fecha desde no puede ser posterior a la fecha hasta.");if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");return e;}public static decimal CalcularStock(decimal actual,string tipo,decimal cantidad)=>tipo is "ING" or "AJP"?actual+cantidad:actual-cantidad;}
